// Home Radar app-shell service worker.
//
// This is intentionally hand-written rather than generated by a build-time
// PWA plugin (e.g. workbox): it only needs to cache the static app shell
// (the HTML/JS/CSS/icons Vite builds), never the live API/data endpoints,
// which live at the same origin with no distinguishing path prefix.
//
// CACHE_NAME and CORE_ASSETS below are placeholders, filled in by
// scripts/inject-sw-precache.mjs right after `vite build` with a
// per-build cache name and the *exact* hashed asset filenames from that
// build (see dist/assets/*). This is what lets the very first visit --
// before this service worker even controls the page -- still precache
// the real JS/CSS bundle at install time, not just "/". Every new build
// gets a fresh cache name, so the activate handler below evicts the
// previous build's entries automatically; nothing lingers across deploys.
const CACHE_NAME = "homeradar-shell-__BUILD_ID__";
const CORE_ASSETS = ["/", "/manifest.webmanifest"]; // __PRECACHE_MANIFEST__

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches
      .open(CACHE_NAME)
      .then((cache) => cache.addAll(CORE_ASSETS))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((key) => key !== CACHE_NAME).map((key) => caches.delete(key))))
      .then(() => self.clients.claim()),
  );
});

function isAppShellRequest(request, url) {
  if (request.mode === "navigate") return true;
  return (
    url.pathname.startsWith("/assets/") ||
    url.pathname.startsWith("/icons/") ||
    url.pathname === "/manifest.webmanifest"
  );
}

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  // Everything else (every dashboard data/API call, the websocket upgrade)
  // is left completely untouched -- always live, never cached, never
  // served stale while offline. Only the static app shell is handled here.
  if (!isAppShellRequest(request, url)) return;

  event.respondWith(
    (async () => {
      try {
        const response = await fetch(request);
        if (response && response.ok) {
          const cache = await caches.open(CACHE_NAME);
          cache.put(request, response.clone());
        }
        return response;
      } catch (networkError) {
        const cached = await caches.match(request, { ignoreSearch: true });
        if (cached) return cached;
        if (request.mode === "navigate") {
          const shell = await caches.match("/");
          if (shell) return shell;
        }
        throw networkError;
      }
    })(),
  );
});
